1	package com.example.starter.firmware;
2	
3	import com.example.starter.firmware.api.CreateReleaseRequest;
4	import com.example.starter.firmware.api.PullResponse;
5	import com.example.starter.firmware.api.ReceiptRequest;
6	import com.example.starter.firmware.api.RegisterDeviceRequest;
7	import com.example.starter.firmware.domain.ReceiptResult;
8	import com.example.starter.firmware.domain.ReleaseStatus;
9	import com.example.starter.firmware.domain.TaskStatus;
10	import com.example.starter.firmware.error.ApiException;
11	import com.example.starter.firmware.repo.ReleaseRepository;
12	import com.example.starter.firmware.repo.TaskRepository;
13	import com.example.starter.firmware.service.DeviceService;
14	import com.example.starter.firmware.service.ReleaseService;
15	import com.example.starter.firmware.service.TaskService;
16	import org.junit.jupiter.api.AfterEach;
17	import org.junit.jupiter.api.BeforeEach;
18	import org.junit.jupiter.api.Test;
19	import org.springframework.beans.factory.annotation.Autowired;
20	import org.springframework.boot.test.context.SpringBootTest;
21	import org.springframework.http.HttpStatus;
22	import org.springframework.jdbc.core.JdbcTemplate;
23	
24	import java.util.ArrayList;
25	import java.util.List;
26	import java.util.concurrent.Callable;
27	import java.util.concurrent.CountDownLatch;
28	import java.util.concurrent.ExecutorService;
29	import java.util.concurrent.Executors;
30	import java.util.concurrent.Future;
31	import java.util.concurrent.TimeUnit;
32	
33	import static org.assertj.core.api.Assertions.assertThat;
34	
35	/**
36	 * 并发与幂等边界测试：真实并发打到 H2 事务与唯一约束上，验证一致提交顺序。
37	 */
38	@SpringBootTest
39	class FirmwareConcurrencyTest {
40	
41	    @Autowired
42	    private DeviceService deviceService;
43	
44	    @Autowired
45	    private ReleaseService releaseService;
46	
47	    @Autowired
48	    private TaskService taskService;
49	
50	    @Autowired
51	    private TaskRepository taskRepository;
52	
53	    @Autowired
54	    private ReleaseRepository releaseRepository;
55	
56	    @Autowired
57	    private JdbcTemplate jdbc;
58	
59	    private ExecutorService executor;
60	
61	    @BeforeEach
62	    void setUp() {
63	        jdbc.update("DELETE FROM rollout_task");
64	        jdbc.update("DELETE FROM release_order");
65	        jdbc.update("DELETE FROM device");
66	        jdbc.update("DELETE FROM idempotency_record");
67	        executor = Executors.newFixedThreadPool(8);
68	    }
69	
70	    @AfterEach
71	    void tearDown() throws InterruptedException {
72	        executor.shutdownNow();
73	        assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
74	    }
75	
76	    /**
77	     * 闩锁对齐后并发执行，收集成功结果与异常。
78	     */
79	    private <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
80	        CountDownLatch ready = new CountDownLatch(tasks.size());
81	        CountDownLatch start = new CountDownLatch(1);
82	        List<Future<Object>> futures = new ArrayList<>();
83	        for (Callable<T> task : tasks) {
84	            futures.add(executor.submit(() -> {
85	                ready.countDown();
86	                start.await(5, TimeUnit.SECONDS);
87	                try {
88	                    return task.call();
89	                } catch (Exception e) {
90	                    return e;
91	                }
92	            }));
93	        }
94	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
95	        start.countDown();
96	        List<Object> results = new ArrayList<>();
97	        for (Future<Object> future : futures) {
98	            results.add(future.get(30, TimeUnit.SECONDS));
99	        }
100	        return results;
101	    }
102	
103	    @Test
104	    void 并发拉取_同设备同发布单最多一条任务() throws Exception {
105	        deviceService.register(new RegisterDeviceRequest("req-d", "d1", "m1", "1.0.0", 5));
106	        long releaseId = releaseService.create(new CreateReleaseRequest("req-r", "m1", "1.0.0", "2.0.0", 100))
107	                .releaseId();
108	
109	        int threads = 8;
110	        List<Callable<PullResponse>> tasks = new ArrayList<>();
111	        for (int i = 0; i < threads; i++) {
112	            int seq = i;
113	            tasks.add(() -> taskService.pull("d1", "req-pull-" + seq));
114	        }
115	        List<Object> results = runConcurrently(tasks);
116	
117	        List<Long> taskIds = new ArrayList<>();
118	        for (Object result : results) {
119	            assertThat(result).isInstanceOf(PullResponse.class);
120	            PullResponse response = (PullResponse) result;
121	            assertThat(response.task()).isNotNull();
122	            taskIds.add(response.task().taskId());
123	        }
124	        assertThat(taskIds).allMatch(id -> id.equals(taskIds.get(0)));
125	        assertThat(taskRepository.countByReleaseAndDevice(releaseId, "d1")).isEqualTo(1);
126	    }
127	
128	    @Test
129	    void 并发创建_同型号至多一张ACTIVE发布单() throws Exception {
130	        List<Callable<Object>> tasks = new ArrayList<>();
131	        for (int i = 0; i < 2; i++) {
132	            int seq = i;
133	            tasks.add(() -> releaseService.create(
134	                    new CreateReleaseRequest("req-c" + seq, "m1", "1.0.0", "2.0.0", 10)).releaseId());
135	        }
136	        List<Object> results = runConcurrently(tasks);
137	
138	        long successes = results.stream().filter(r -> !(r instanceof Exception)).count();
139	        long conflicts = results.stream()
140	                .filter(r -> r instanceof ApiException ae && ae.status() == HttpStatus.CONFLICT)
141	                .count();
142	        assertThat(successes).isEqualTo(1);
143	        assertThat(conflicts).isEqualTo(1);
144	        Long active = jdbc.queryForObject(
145	                "SELECT COUNT(*) FROM release_order WHERE status = 'ACTIVE'", Long.class);
146	        assertThat(active).isEqualTo(1);
147	    }
148	
149	    @Test
150	    void 并发拉取与取消_最终状态一致() throws Exception {
151	        for (int round = 0; round < 10; round++) {
152	            String deviceId = "d" + round;
153	            String model = "m" + round;
154	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
155	            long releaseId = releaseService.create(
156	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
157	            final int seq = round;
158	
159	            List<Object> results = runConcurrently(List.of(
160	                    (Callable<Object>) () -> taskService.pull(deviceId, "req-p" + seq),
161	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
162	            assertThat(results).noneMatch(r -> r instanceof Exception && !(r instanceof ApiException));
163	
164	            assertThat(releaseService.findOrder(releaseId).status()).isEqualTo(ReleaseStatus.CANCELLED);
165	            Long pending = jdbc.queryForObject(
166	                    "SELECT COUNT(*) FROM rollout_task WHERE release_id = ? AND status = 'PENDING'",
167	                    Long.class, releaseId);
168	            assertThat(pending).as("取消后不得残留 PENDING 任务（第%d轮）", round).isZero();
169	        }
170	    }
171	
172	    @Test
173	    void 并发成功回执与取消_一致提交顺序且已成功不回滚() throws Exception {
174	        int successWins = 0;
175	        int cancelWins = 0;
176	        for (int round = 0; round < 10; round++) {
177	            String deviceId = "d" + round;
178	            String model = "m" + round;
179	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
180	            long releaseId = releaseService.create(
181	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
182	            long taskId = taskService.pull(deviceId, "req-p" + round).task().taskId();
183	            final int seq = round;
184	
185	            List<Object> results = runConcurrently(List.of(
186	                    (Callable<Object>) () -> taskService.receipt(taskId,
187	                            new ReceiptRequest("req-s" + seq, ReceiptResult.SUCCESS)),
188	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
189	
190	            Object receiptResult = results.get(0);
191	            TaskStatus finalStatus = taskRepository.findById(taskId).orElseThrow().status();
192	            String deviceVersion = deviceService.get(deviceId).currentVersion();
193	            if (finalStatus == TaskStatus.SUCCESS) {
194	                successWins++;
195	                assertThat(receiptResult).isNotInstanceOf(Exception.class);
196	                assertThat(deviceVersion).isEqualTo("2.0.0");
197	            } else {
198	                cancelWins++;
199	                assertThat(finalStatus).isEqualTo(TaskStatus.CANCELLED);
200	                assertThat(receiptResult).isInstanceOfSatisfying(ApiException.class,
201	                        ae -> assertThat(ae.status()).isEqualTo(HttpStatus.CONFLICT));
202	                assertThat(deviceVersion).isEqualTo("1.0.0");
203	            }
204	            // 取消后任务不再处于 PENDING，且已成功设备不回滚
205	            assertThat(finalStatus).isNotEqualTo(TaskStatus.PENDING);
206	        }
207	        assertThat(successWins + cancelWins).isEqualTo(10);
208	    }
209	
210	    @Test
211	    void 并发同requestId_重放一致且副作用只发生一次() throws Exception {
212	        deviceService.register(new RegisterDeviceRequest("req-d", "d1", "m1", "1.0.0", 5));
213	        long releaseId = releaseService.create(new CreateReleaseRequest("req-r", "m1", "1.0.0", "2.0.0", 10))
214	                .releaseId();
215	
216	        int threads = 6;
217	        List<Callable<Object>> tasks = new ArrayList<>();
218	        for (int i = 0; i < threads; i++) {
219	            tasks.add(() -> releaseService.expand(releaseId,
220	                    new com.example.starter.firmware.api.ExpandReleaseRequest("req-same", 1, 60)));
221	        }
222	        List<Object> results = runConcurrently(tasks);
223	
224	        for (Object result : results) {
225	            assertThat(result).isNotInstanceOf(Exception.class);
226	        }
227	        // 版本只加一次，证明重放而非重复执行
228	        assertThat(releaseService.findOrder(releaseId).version()).isEqualTo(2);
229	        assertThat(releaseService.findOrder(releaseId).ratio()).isEqualTo(60);
230	    }
231	}
