package com.example.starter.firmware.domain;

/**
 * 发布单状态：ACTIVE 投放中；PAUSED 失败自动暂停；COMPLETED 已完成（终态）；CANCELLED 已取消（终态）。
 */
public enum ReleaseStatus {
    ACTIVE,
    PAUSED,
    COMPLETED,
    CANCELLED
}

package com.example.starter.firmware.domain;

/**
 * 固件灰度发布单。
 *
 * @param id           发布单ID
 * @param version      发布单版本号，从1开始，每次扩量成功加一
 * @param model        目标设备型号
 * @param fromVersion  来源固件版本
 * @param toVersion    目标固件版本，必须与来源版本不同
 * @param ratio        当前生效投放比例，取值0~100；分级发布单等于当前解锁级别比例，只增不减
 * @param status       状态：ACTIVE 投放中，PAUSED 失败自动暂停，COMPLETED 已完成，CANCELLED 已取消
 * @param currentLevel 当前已解锁最高金丝雀级别，从1开始；未配置分级时恒为1
 */
public record ReleaseOrder(long id, int version, String model, String fromVersion, String toVersion,
                           int ratio, ReleaseStatus status, int currentLevel) {
}

package com.example.starter.firmware.domain;

/**
 * 金丝雀分级验证级别。样本与失败计数随首次终结回执累计，推进后不重置。
 *
 * @param id             级别ID
 * @param releaseId      所属发布单ID
 * @param levelNo        级别序号，从1开始递增
 * @param ratio          该级别投放比例，取值1~100，同一发布单内逐级递增
 * @param minSamples     推进所需最小验证样本数，取值1~50
 * @param maxFailureRate 失败率上限，单位百分比，取值1~100；超过即触发失败自动暂停
 * @param sampleCount    该级别已计入的首次终结回执样本数
 * @param failedCount    该级别样本中首次结果为FAILED的数量
 */
public record CanaryLevel(long id, long releaseId, int levelNo, int ratio, int minSamples,
                          int maxFailureRate, int sampleCount, int failedCount) {

    /**
     * 失败率是否超过上限（整数运算，避免浮点误差）。
     */
    public boolean failureRateExceeded() {
        return sampleCount > 0 && failedCount * 100L > (long) maxFailureRate * sampleCount;
    }

    /**
     * 失败率百分比，保留两位小数；无样本时为0。
     */
    public double failureRatePercent() {
        if (sampleCount == 0) {
            return 0.0;
        }
        return Math.round(failedCount * 10000.0 / sampleCount) / 100.0;
    }
}

package com.example.starter.firmware.domain;

/**
 * 金丝雀级别推进历史记录，只增不改。
 *
 * @param id          推进记录ID
 * @param releaseId   所属发布单ID
 * @param fromLevel   推进前已解锁最高级别
 * @param toLevel     新解锁级别；推进到终态 COMPLETED 时为 null
 * @param action      动作：UNLOCK 解锁下一级别，COMPLETE 进入完成终态
 * @param sampleCount 推进时当前级别样本数快照
 * @param failedCount 推进时当前级别失败样本数快照
 * @param promoteKey  本次推进的幂等键（全局唯一）
 */
public record CanaryPromotion(long id, long releaseId, int fromLevel, Integer toLevel, String action,
                              int sampleCount, int failedCount, String promoteKey) {
}

